    "seo.careers.benefit4_title": "Flexible PTO",
    "seo.careers.benefit4_desc":
      "Unlimited paid time off to maintain healthy work-life balance. Take time when you need it.",
    "seo.careers.benefit5_title": "Competitive Pay",
    "seo.careers.benefit5_desc":
      "Market-leading salaries with annual reviews, equity options, and performance bonuses.",
    "seo.careers.benefit6_title": "Annual Retreats",
    "seo.careers.benefit6_desc":
      "Fully-paid team retreats in exciting locations to connect, collaborate, and celebrate together.",
    "seo.careers.departments_title": "Departments We're Hiring For",
    "seo.careers.dept_eng": "Engineering",
