    "seo.careers.process_title": "Our Hiring Process",
    "seo.careers.step1_title": "Application",
    "seo.careers.step1_desc":
      "Submit your resume and a brief note about why you're excited about Calculator12.",
    "seo.careers.step2_title": "Screening Call",
    "seo.careers.step2_desc":
      "A 30-minute conversation with our talent team to learn about your background and goals.",
    "seo.careers.step3_title": "Skills Assessment",
    "seo.careers.step3_desc":
      "A practical task or project relevant to the role, designed to showcase your abilities.",
    "seo.careers.step4_title": "Team Interview",
    "seo.careers.step4_desc":
      "Meet your potential teammates and discuss how you'd collaborate on real projects.",
